<script setup>
import {onMounted,ref} from 'vue';import SiteHeader from '../components/SiteHeader.vue';import SiteFooter from '../components/SiteFooter.vue';import FeeBreakdown from '../components/FeeBreakdown.vue';import {getCollegeContent} from '../services/api';
const data=ref({site:{},programs:[]}),loading=ref(true),error=ref('');
onMounted(async()=>{try{data.value=(await getCollegeContent()).data.data;document.title=`Programs | ${data.value.site.college_name||'College of Nursing'}`}catch{error.value='Programs could not be loaded. Please try again.'}finally{loading.value=false}});
</script>
<template><SiteHeader :site="data.site" active="programs"/><main><section class="programs-hero"><div class="container"><span class="eyebrow text-info">ACADEMIC PROGRAMS</span><h1>Find Your Path<br>in Nursing</h1><p>Explore every nursing program offered by our college and choose the path that matches your professional goals.</p><router-link to="/contact" class="btn btn-primary">Talk to Admissions</router-link></div></section>
<section class="section section-soft"><div class="container"><div class="programs-page-heading"><div><span class="eyebrow">OUR PROGRAMS</span><h2>All Nursing Programs</h2><p>Career-focused education supported by modern laboratories and supervised clinical experience.</p></div><router-link to="/" class="back-home"><i class="bi bi-arrow-left"></i> Back to home</router-link></div><div v-if="loading" class="text-center py-5"><div class="spinner-border text-primary" role="status"><span class="visually-hidden">Loading programs</span></div></div><div v-else-if="error" class="alert alert-danger">{{error}}</div><div v-else-if="!data.programs.length" class="empty-programs"><i class="bi bi-journal-medical"></i><h3>No programs are currently published.</h3><p>Please contact admissions for current course information.</p></div><div v-else class="row g-4"><div class="col-md-6 col-xl-4" v-for="program in data.programs" :key="program.id"><article class="program-list-card"><img :src="program.image_url||'/images/nursing-hero.png'" :alt="program.name"><div class="program-list-body"><span class="program-duration"><i class="bi bi-clock"></i> {{program.duration}}</span><h2>{{program.name}}</h2><p>{{program.description}}</p><FeeBreakdown :fees="program.fees"/><div class="program-actions"><router-link to="/apply" class="btn btn-primary">Apply Now</router-link><a :href="`mailto:${data.site.college_email||'admissions@example.edu'}`" class="details-link">Request details <i class="bi bi-arrow-right"></i></a></div></div></article></div></div></div></section>
<section class="programs-cta"><div class="container text-center"><span class="eyebrow text-info">NEED GUIDANCE?</span><h2>Not Sure Which Program Is Right for You?</h2><p>Our admissions team can help you compare programs, entry requirements, and career pathways.</p><router-link to="/#apply" class="btn btn-primary btn-lg">Speak With Admissions</router-link></div></section></main><SiteFooter :site="data.site"/></template>
